3	```solidity
4	// SPDX-License-Identifier: MIT
5	pragma solidity 0.8.36;
6	
7	import { VRFV2PlusWrapperConsumerBase } from "@chainlink/contracts/src/v0.8/vrf/dev/VRFV2PlusWrapperConsumerBase.sol";
8	import { IVRFV2PlusWrapper } from "@chainlink/contracts/src/v0.8/vrf/dev/interfaces/IVRFV2PlusWrapper.sol";
9	import { VRFV2PlusClient } from "@chainlink/contracts/src/v0.8/vrf/dev/libraries/VRFV2PlusClient.sol";
10	import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
11	import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
12	import { ERC721 } from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
13	import { IERC721 } from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
14	import { IERC721Receiver } from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
15	import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
16	import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
17	
18	import { IRaffle } from "./interfaces/IRaffle.sol";
19	import { IRaffleFactory } from "./interfaces/IRaffleFactory.sol";
20	import { RaffleConstants } from "./libraries/RaffleConstants.sol";
21	
22	/// @title raffle.fun Raffle Escrow and Entry Ticket
23	/// @author heesho
24	/// @notice Escrows one NFT and sells fixed-price USDC entries through one transferable ERC-721 ticket per purchase.
25	/// @dev Ticket IDs are sequential and map to one inclusive `[firstEntry,lastEntry]` uint128 range. Purchases, Chainlink
26	///      callbacks, and winner proofs are O(1) in entry count. Tickets remain transferable bearer claims until their
27	///      owners burn them for redemption or refund. Each raffle is a fixed, non-upgradeable ERC-1167 clone with no
28	///      administrator or rescue path. Permissionless settlement only allocates liabilities; the winning-ticket owner
29	///      atomically burns the ticket while receiving the NFT or cash prize.
30	/// @custom:version 1.0.0
31	contract Raffle is IRaffle, ERC721, ReentrancyGuard, IERC721Receiver, VRFV2PlusWrapperConsumerBase {
32	    using SafeERC20 for IERC20;
33	
34	    // Types
35	
36	    /// @notice Inclusive global entry-number range represented by one sequential ERC-721 ticket.
37	    /// @param firstEntry First represented one-based global entry.
38	    /// @param lastEntry Last represented one-based global entry.
39	    struct TicketRange {
40	        uint128 firstEntry;
41	        uint128 lastEntry;
42	    }
43	
44	    // Constants
45	
46	    /// @inheritdoc IRaffle
47	    uint256 public constant override ENTRY_PRICE = RaffleConstants.ENTRY_PRICE;
48	
49	    /// @inheritdoc IRaffle
50	    uint32 public constant override callbackGasLimit = RaffleConstants.VRF_CALLBACK_GAS_LIMIT;
51	
52	    /// @inheritdoc IRaffle
53	    uint16 public constant override requestConfirmations = RaffleConstants.VRF_REQUEST_CONFIRMATIONS;
54	
55	    // Immutables and state
56	
57	    /// @inheritdoc IRaffle
58	    address public immutable override factory;
59	
60	    /// @inheritdoc IRaffle
61	    IERC20 public immutable override quoteToken;
62	
63	    /// @inheritdoc IRaffle
64	    address public override sponsor;
65	
66	    /// @inheritdoc IRaffle
67	    address public override sponsorRecipient;
68	
69	    /// @inheritdoc IRaffle
70	    address public override protocolTreasury;
71	
72	    /// @inheritdoc IRaffle
73	    IERC721 public override prizeToken;
74	
75	    /// @inheritdoc IRaffle
76	    uint256 public override prizeTokenId;
77	
78	    /// @inheritdoc IRaffle
79	    uint256 public override raffleId;
80	
81	    /// @inheritdoc IRaffle
82	    uint128 public override reserveEntries;
83	
84	    /// @inheritdoc IRaffle
85	    uint64 public override endTime;
86	
87	    /// @inheritdoc IRaffle
88	    uint128 public override totalEntries;
89	
90	    /// @inheritdoc IRaffle
91	    uint128 public override ticketCount;
92	
93	    /// @inheritdoc IRaffle
94	    uint256 public override unsettledPot;
95	
96	    /// @inheritdoc IRaffle
97	    uint256 public override remainingRefundLiability;
98	
99	    /// @inheritdoc IRaffle
100	    address public override winnerRecipient;
101	
102	    /// @inheritdoc IRaffle
103	    uint256 public override winnerProceeds;
104	
105	    /// @inheritdoc IRaffle
106	    uint256 public override sponsorProceeds;
107	
108	    /// @inheritdoc IRaffle
109	    uint256 public override protocolFees;
110	
111	    /// @inheritdoc IRaffle
112	    uint256 public override vrfRequestId;
113	
114	    /// @inheritdoc IRaffle
115	    uint64 public override drawRequestedAt;
116	
117	    /// @inheritdoc IRaffle
118	    uint64 public override resolvedAt;
119	
120	    /// @inheritdoc IRaffle
121	    uint128 public override winningEntry;
122	
123	    /// @inheritdoc IRaffle
124	    uint256 public override winningTicketId;
125	
126	    /// @inheritdoc IRaffle
127	    Status public override status;
128	
129	    /// @inheritdoc IRaffle
130	    bool public override settlementComplete;
131	
132	    /// @inheritdoc IRaffle
133	    bool public override winnerRedeemed;
134	
135	    /// @inheritdoc IRaffle
136	    bool public override prizeClaimed;
137	
138	    /// @inheritdoc IRaffle
139	    bool public override initialized;
140	
141	    /// @dev Historical ticket ranges remain stored after burns so indexers and callers can reconstruct entry coverage.
142	    mapping(uint256 ticketId => TicketRange range) private _ticketRanges;
143	
144	    /// @dev True only while the wrapper request call is executing, so a synchronous callback cannot resolve early.
145	    bool private _requestInFlight;
146	
147	    // Errors
148	
149	    /// @notice Raised when native currency is sent outside the payable draw-request path.
150	    error DirectNativeTransfer();
151	
152	    // Constructor
153	
154	    /// @notice Deploys and locks the implementation shared by one factory's minimal-proxy raffles.
155	    /// @dev Constructor state belongs to the implementation. Clones share these immutables but hold isolated storage.
156	    /// @param quoteToken_ Canonical six-decimal USDC contract fixed for the implementation and every clone.
157	    /// @param vrfWrapper_ Chainlink VRF v2.5 native direct-funding wrapper fixed for the implementation and all clones.
158	    constructor(address quoteToken_, address vrfWrapper_)
159	        ERC721("", "")
160	        VRFV2PlusWrapperConsumerBase(_validatedVrfWrapper(vrfWrapper_))
161	    {
162	        if (msg.sender == address(0) || quoteToken_ == address(0)) revert ZeroAddress();
163	
164	        factory = msg.sender;
165	        quoteToken = IERC20(quoteToken_);
166	
167	        initialized = true;
168	        status = Status.Refunding;
169	    }
170	
171	    // External state-changing functions
172	
173	    /// @notice Rejects direct native-token transfers that are not attached to `requestDraw`.
174	    receive() external payable {
175	        revert DirectNativeTransfer();
176	    }
177	
178	    /// @inheritdoc IRaffle
179	    function initialize(RaffleInitParams calldata params) external override {
180	        if (initialized) revert AlreadyInitialized();
181	        if (msg.sender != factory) revert OnlyFactory();
182	        initialized = true;
183	
184	        if (
185	            params.sponsor == address(0) || params.sponsorRecipient == address(0)
186	                || params.protocolTreasury == address(0) || params.prizeToken == address(0)
187	        ) {
188	            revert ZeroAddress();
189	        }
190	        if (_isProtocolDestination(params.sponsor, params.prizeToken)) {
191	            revert UnsafeProtocolDestination(params.sponsor);
192	        }
193	        if (_isProtocolDestination(params.protocolTreasury, params.prizeToken)) {
194	            revert UnsafeProtocolDestination(params.protocolTreasury);
195	        }
196	        if (_isProtocolDestination(params.sponsorRecipient, params.prizeToken)) {
197	            revert UnsafeProtocolDestination(params.sponsorRecipient);
198	        }
199	
200	        sponsor = params.sponsor;
201	        sponsorRecipient = params.sponsorRecipient;
202	        protocolTreasury = params.protocolTreasury;
203	        prizeToken = IERC721(params.prizeToken);
204	        prizeTokenId = params.prizeTokenId;
205	        raffleId = params.raffleId;
206	        reserveEntries = params.reserveEntries;
207	        endTime = params.endTime;
208	        status = Status.AwaitingPrize;
209	    }
210	
211	    /// @inheritdoc IRaffle
212	    function buyEntries(address recipient, uint128 entryCount)
213	        external
214	        override
215	        nonReentrant
216	        returns (uint256 ticketId)
217	    {
218	        _requireStatus(Status.Active);
219	        if (block.timestamp >= endTime) revert SaleEnded(endTime, block.timestamp);
220	        if (recipient == address(0)) revert InvalidRecipient();
221	        if (entryCount == 0) revert ZeroEntryCount();
222	        if (entryCount > type(uint128).max - totalEntries) {
223	            revert TotalEntriesOverflow(totalEntries, entryCount);
224	        }
225	
226	        uint256 grossAmount = uint256(entryCount) * ENTRY_PRICE;
227	        quoteToken.safeTransferFrom(msg.sender, address(this), grossAmount);
228	
229	        uint128 firstEntry = totalEntries + 1;
230	        uint128 lastEntry = totalEntries + entryCount;
231	        ticketId = uint256(ticketCount) + 1;
232	
233	        totalEntries = lastEntry;
234	        ++ticketCount;
235	        _ticketRanges[ticketId] = TicketRange({ firstEntry: firstEntry, lastEntry: lastEntry });
236	        unsettledPot += grossAmount;
237	
238	        _safeMint(recipient, ticketId);
239	        emit TicketPurchased(msg.sender, recipient, ticketId, firstEntry, lastEntry, entryCount, grossAmount);
240	    }
241	
242	    /// @inheritdoc IRaffle
243	    function requestDraw() external payable override nonReentrant returns (uint256 requestId) {
244	        _requireStatus(Status.Active);
245	        if (block.timestamp < endTime) revert RaffleNotEnded(endTime, block.timestamp);
246	        if (totalEntries == 0) revert NoEntriesSold();
247	        uint256 requestDeadline = drawRequestDeadline();
248	        if (block.timestamp >= requestDeadline) {
249	            revert DrawRequestWindowExpired(requestDeadline, block.timestamp);
250	        }
251	
252	        uint256 quotedFee = getVrfRequestPrice();
253	        if (msg.value < quotedFee) revert InsufficientVrfFee(quotedFee, msg.value);
254	
255	        status = Status.Drawing;
256	        drawRequestedAt = uint64(block.timestamp);
257	        _requestInFlight = true;
258	        bytes memory extraArgs = VRFV2PlusClient._argsToBytes(VRFV2PlusClient.ExtraArgsV1({ nativePayment: true }));
259	        uint256 paidPrice;
260	        (requestId, paidPrice) = requestRandomnessPayInNative(callbackGasLimit, requestConfirmations, 1, extraArgs);
261	        if (paidPrice > msg.value) revert InsufficientVrfFee(paidPrice, msg.value);
262	        vrfRequestId = requestId;
263	        _requestInFlight = false;
264	
265	        uint256 excess = msg.value - paidPrice;
266	        if (excess != 0) {
267	            bool success;
268	            address refundRecipient = msg.sender;
269	            assembly ("memory-safe") {
270	                success := call(gas(), refundRecipient, excess, 0, 0, 0, 0)
271	            }
272	            if (!success) revert NativeRefundFailed(msg.sender, excess);
273	        }
274	
275	        emit DrawRequested(requestId, msg.sender, paidPrice, excess, drawRequestedAt, callbackDeadline());
276	    }
277	
278	    /// @inheritdoc IRaffle
279	    function enableRefunds() external override nonReentrant {
280	        uint256 deadline;
281	
282	        if (status == Status.Active) {
283	            if (totalEntries == 0) {
284	                deadline = endTime;
285	                if (msg.sender != sponsor && block.timestamp < deadline) {
286	                    revert RefundsNotAvailable(deadline, block.timestamp);
287	                }
288	            } else {
289	                deadline = drawRequestDeadline();
290	                if (block.timestamp < deadline) revert RefundsNotAvailable(deadline, block.timestamp);
291	            }
292	        } else if (status == Status.Drawing) {
293	            deadline = callbackDeadline();
294	            if (block.timestamp < deadline) revert RefundsNotAvailable(deadline, block.timestamp);
295	        } else {
296	            revert InvalidStatus(status);
297	        }
298	
299	        uint256 liability = unsettledPot;
300	        unsettledPot = 0;
301	        remainingRefundLiability = liability;
302	        status = Status.Refunding;
303	        emit RefundsEnabled(msg.sender, liability);
304	    }
305	
306	    /// @inheritdoc IRaffle
307	    function settleWinningTicket(uint256 ticketId) external override nonReentrant returns (uint256 cashAmount) {
308	        cashAmount = _settleWinningTicket(ticketId);
309	    }
310	
311	    /// @inheritdoc IRaffle
312	    function redeemWinningTicket(uint256 ticketId) external override nonReentrant returns (uint256 cashAmount) {
313	        if (winnerRedeemed) revert WinningTicketAlreadyRedeemed();
314	        Status result = status;
315	        if (result != Status.NftWon && result != Status.CashWon) revert InvalidStatus(result);
316	
317	        if (!settlementComplete) {
318	            _settleWinningTicket(ticketId);
319	        } else if (ticketId != winningTicketId) {
320	            revert WinningTicketMismatch(ticketId, winningTicketId);
321	        }
322	
323	        address winner = ownerOf(ticketId);
324	        if (msg.sender != winner) revert NotTicketOwner(ticketId, msg.sender, winner);
325	
326	        winnerRecipient = winner;
327	        winnerRedeemed = true;
328	        _burn(ticketId);
329	
330	        address deliveredPrizeToken = address(0);
331	        uint256 deliveredPrizeTokenId = 0;
332	        if (result == Status.NftWon) {
333	            if (prizeClaimed) revert PrizeAlreadyClaimed();
334	            prizeClaimed = true;
335	            deliveredPrizeToken = address(prizeToken);
336	            deliveredPrizeTokenId = prizeTokenId;
337	            prizeToken.transferFrom(address(this), winner, deliveredPrizeTokenId);
338	            if (prizeToken.ownerOf(deliveredPrizeTokenId) != winner) {
339	                revert PrizeDeliveryVerificationFailed(winner);
340	            }
341	        } else {
342	            cashAmount = winnerProceeds;
343	            if (cashAmount == 0) revert NoWinnerProceeds();
344	            winnerProceeds = 0;
345	            _transferQuote(winner, cashAmount);
346	        }
347	
348	        emit WinningTicketRedeemed(ticketId, winner, result, cashAmount, deliveredPrizeToken, deliveredPrizeTokenId);
349	    }
350	
351	    /// @inheritdoc IRaffle
352	    function refundTickets(uint256[] calldata ticketIds) external override nonReentrant returns (uint256 amount) {
353	        _requireStatus(Status.Refunding);
354	        uint256 ticketQuantity = ticketIds.length;
355	        if (ticketQuantity == 0 || ticketQuantity > RaffleConstants.MAX_REFUND_TICKET_BATCH_SIZE) {
356	            revert InvalidTicketBatchSize(ticketQuantity, RaffleConstants.MAX_REFUND_TICKET_BATCH_SIZE);
357	        }
358	
359	        uint256 aggregateEntries = 0;
360	        for (uint256 index; index < ticketQuantity; ++index) {
361	            uint256 ticketId = ticketIds[index];
362	            address owner = ownerOf(ticketId);
363	            if (msg.sender != owner) revert NotTicketOwner(ticketId, msg.sender, owner);
364	
365	            (uint128 firstEntry, uint128 lastEntry) = ticketRange(ticketId);
366	            aggregateEntries += uint256(lastEntry) - uint256(firstEntry) + 1;
367	            _burn(ticketId);
368	        }
369	
370	        amount = aggregateEntries * ENTRY_PRICE;
371	        remainingRefundLiability -= amount;
372	        _transferQuote(msg.sender, amount);
373	        uint256 liabilityAfter = remainingRefundLiability;
374	        emit TicketsRefunded(msg.sender, ticketQuantity, aggregateEntries, amount, liabilityAfter);
375	    }
376	
377	    /// @inheritdoc IRaffle
378	    function releaseSponsorProceeds() external override nonReentrant returns (uint256 amount) {
379	        amount = sponsorProceeds;
380	        if (amount == 0) revert NoSponsorProceeds();
381	        sponsorProceeds = 0;
382	        address recipient = sponsorRecipient;
383	        _transferQuote(recipient, amount);
384	        emit SponsorProceedsReleased(msg.sender, recipient, amount);
385	    }
386	
387	    /// @inheritdoc IRaffle
388	    function releaseProtocolFees() external override nonReentrant returns (uint256 amount) {
389	        amount = protocolFees;
390	        if (amount == 0) revert NoProtocolFees();
391	        protocolFees = 0;
392	        address treasury = protocolTreasury;
393	        _transferQuote(treasury, amount);
394	        emit ProtocolFeesReleased(msg.sender, treasury, amount);
395	    }
396	
397	    /// @inheritdoc IRaffle
398	    function releaseSponsorPrize() external override nonReentrant {
399	        Status currentStatus = status;
400	        if (currentStatus != Status.CashWon && currentStatus != Status.Refunding) {

400	        if (currentStatus != Status.CashWon && currentStatus != Status.Refunding) {
401	            revert SponsorPrizeUnavailable(currentStatus);
402	        }
403	        if (prizeClaimed) revert PrizeAlreadyClaimed();
404	
405	        address recipient = sponsorRecipient;
406	        prizeClaimed = true;
407	        prizeToken.transferFrom(address(this), recipient, prizeTokenId);
408	        if (prizeToken.ownerOf(prizeTokenId) != recipient) revert PrizeDeliveryVerificationFailed(recipient);
409	        emit SponsorPrizeReleased(msg.sender, recipient, address(prizeToken), prizeTokenId);
410	    }
411	
412	    /// @notice Accepts only the exact configured prize deposited by the factory for the sponsor.
413	    /// @dev Unrelated NFTs forced here with unsafe `transferFrom` remain outside protocol accounting and cannot be
414	    ///      rescued.
415	    /// @param operator ERC-721 transfer operator, which must be the canonical factory.
416	    /// @param from Previous owner, which must be the configured sponsor.
417	    /// @param tokenId Transferred token ID, which must match the configured prize.
418	    /// @return selector ERC-721 receiver acceptance selector.
419	    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata)
420	        external
421	        override
422	        returns (bytes4 selector)
423	    {
424	        if (
425	            status != Status.AwaitingPrize || msg.sender != address(prizeToken) || tokenId != prizeTokenId
426	                || from != sponsor || operator != factory
427	        ) {
428	            revert UnexpectedPrize(msg.sender, tokenId, from, operator);
429	        }
430	
431	        status = Status.Active;
432	        emit PrizeDeposited(msg.sender, tokenId, from);
433	        selector = IERC721Receiver.onERC721Received.selector;
434	    }
435	
436	    // Public view and pure functions
437	
438	    /// @inheritdoc IRaffle
439	    function getVrfRequestPrice() public view override returns (uint256 fee) {
440	        fee = i_vrfV2PlusWrapper.calculateRequestPriceNative(callbackGasLimit, 1);
441	    }
442	
443	    /// @inheritdoc IRaffle
444	    function estimateVrfRequestPrice(uint256 requestGasPriceWei) public view override returns (uint256 fee) {
445	        fee = i_vrfV2PlusWrapper.estimateRequestPriceNative(callbackGasLimit, 1, requestGasPriceWei);
446	    }
447	
448	    /// @inheritdoc IRaffle
449	    function vrfWrapper() public view override returns (IVRFV2PlusWrapper wrapper) {
450	        wrapper = i_vrfV2PlusWrapper;
451	    }
452	
453	    /// @inheritdoc IRaffle
454	    function ticketRange(uint256 ticketId) public view override returns (uint128 firstEntry, uint128 lastEntry) {
455	        TicketRange storage range = _ticketRanges[ticketId];
456	        firstEntry = range.firstEntry;
457	        lastEntry = range.lastEntry;
458	    }
459	
460	    /// @inheritdoc IRaffle
461	    function drawRequestDeadline() public view override returns (uint256 deadline) {
462	        deadline = uint256(endTime) + RaffleConstants.DRAW_REQUEST_TIMEOUT;
463	    }
464	
465	    /// @inheritdoc IRaffle
466	    function callbackDeadline() public view override returns (uint256 deadline) {
467	        if (drawRequestedAt != 0) deadline = uint256(drawRequestedAt) + RaffleConstants.DRAW_CALLBACK_TIMEOUT;
468	    }
469	
470	    /// @inheritdoc IRaffle
471	    function accountedQuoteBalance() public view override returns (uint256 amount) {
472	        amount = unsettledPot + remainingRefundLiability + winnerProceeds + sponsorProceeds + protocolFees;
473	    }
474	
475	    /// @inheritdoc IRaffle
476	    function grossSales() public view override returns (uint256 amount) {
477	        amount = uint256(totalEntries) * ENTRY_PRICE;
478	    }
479	
480	    /// @notice Returns the fixed display name shared by every raffle ticket collection.
481	    /// @return Exact ERC-721 collection name, `raffle.fun Ticket`.
482	    function name() public pure override returns (string memory) {
483	        return "raffle.fun Ticket";
484	    }
485	
486	    /// @notice Returns the fixed display symbol shared by every raffle ticket collection.
487	    /// @return Exact ERC-721 collection symbol, `RAFFLE`.
488	    function symbol() public pure override returns (string memory) {
489	        return "RAFFLE";
490	    }
491	
492	    // Internal state-changing functions
493	
494	    /// @dev Tickets remain transferable bearer claims in every lifecycle state. Known protocol sinks are rejected
495	    ///      before their ownership could make a claim unreachable. Burns pass the zero address and remain permitted.
496	    /// @param to Prospective ticket recipient, or the zero address for a burn.
497	    /// @param ticketId Ticket being minted, transferred, or burned.
498	    /// @param auth Caller whose owner or operator authority is checked by ERC-721.
499	    /// @return previousOwner Ticket owner before the update, or the zero address for a mint.
500	    function _update(address to, uint256 ticketId, address auth) internal override returns (address previousOwner) {
501	        if (to != address(0) && _isProtocolDestination(to, address(prizeToken))) {
502	            revert UnsafeProtocolDestination(to);
503	        }
504	        previousOwner = super._update(to, ticketId, auth);
505	    }
506	
507	    /// @dev Authenticated randomness selects only an entry. No ticket search, loop, user call, or token transfer
508	    ///      occurs. In-flight, late, wrong-request, duplicate, and ABI-decodable wrong-length callbacks are ignored for
509	    ///      liveness; malformed ABI calldata reverts during Solidity decoding before this handler runs.
510	    /// @param requestId Wrapper-authenticated request identifier supplied by the callback.
511	    /// @param randomWords Callback words; exactly one word is required for resolution.
512	    function fulfillRandomWords(uint256 requestId, uint256[] memory randomWords) internal override {
513	        if (
514	            _requestInFlight || status != Status.Drawing || requestId != vrfRequestId || randomWords.length != 1
515	                || block.timestamp >= callbackDeadline()
516	        ) {
517	            emit VrfCallbackIgnored(requestId, vrfRequestId, status);
518	            return;
519	        }
520	
521	        uint128 resolvedEntry = uint128((randomWords[0] % uint256(totalEntries)) + 1);
522	        winningEntry = resolvedEntry;
523	        resolvedAt = uint64(block.timestamp);
524	        status = totalEntries >= reserveEntries ? Status.NftWon : Status.CashWon;
525	
526	        emit RaffleResolved(requestId, resolvedEntry, status);
527	    }
528	
529	    // Private state-changing helpers
530	
531	    /// @dev Validates the winning range once and allocates all terminal quote-token liabilities without transferring
532	    ///      an asset or reading ticket ownership. Both percentage allocations round down; sponsor proceeds are the
533	    ///      remainder.
534	    /// @param ticketId Ticket whose inclusive range must contain the selected winning entry.
535	    /// @return cashAmount Raw six-decimal quote-token units allocated to the cash winner, or zero for `NftWon`.
536	    function _settleWinningTicket(uint256 ticketId) private returns (uint256 cashAmount) {
537	        if (settlementComplete) revert SettlementAlreadyComplete();
538	        Status result = status;
539	        if (result != Status.NftWon && result != Status.CashWon) revert InvalidStatus(result);
540	
541	        _requireWinningTicket(ticketId);
542	        uint256 grossPot = unsettledPot;
543	        uint256 protocolFee = Math.mulDiv(grossPot, RaffleConstants.PROTOCOL_FEE_BPS, RaffleConstants.BPS);
544	        uint256 sponsorAmount;
545	
546	        if (result == Status.NftWon) {
547	            sponsorAmount = grossPot - protocolFee;
548	        } else {
549	            cashAmount = Math.mulDiv(grossPot, RaffleConstants.CASH_WINNER_BPS, RaffleConstants.BPS);
550	            sponsorAmount = grossPot - protocolFee - cashAmount;
551	            winnerProceeds = cashAmount;
552	        }
553	
554	        settlementComplete = true;
555	        winningTicketId = ticketId;
556	        unsettledPot = 0;
557	        sponsorProceeds = sponsorAmount;
558	        protocolFees = protocolFee;
559	
560	        emit WinningTicketSettled(ticketId, msg.sender, result, cashAmount, protocolFee, sponsorAmount);
561	    }
562	
563	    /// @dev Transfers one complete current USDC claim through SafeERC20 after rejecting known protocol sinks. The
564	    ///      canonical USDC trust model assumes standard, non-rebasing, fee-free transfer semantics.
565	    /// @param to Immutable or owner-derived recipient of the claim.
566	    /// @param amount Raw six-decimal USDC units transferred.
